methods.Service/OptionService.php::add:
function add(
		int $pollId,
		SimpleOption $simpleOption,
		bool $voteYes = false,
	): Option {
		$this->getPoll($pollId)->request(Poll::PERMISSION_OPTION_ADD);

		// Build the new option
		$newOption = new Option();
		$newOption->setPoll($this->poll->getId());
		// A new option initially is positioned at the end of the list
		$newOption->setOrder($this->getHighestOrder($pollId) + 1);
		$newOption->setFromSimpleOption($simpleOption, $this->poll->getType());

		if (!$this->poll->getIsPollOwner()) {
			$newOption->setOwner($this->userSession->getCurrentUserId());
		}
		try {
			// Insert the new option
			$newOption = $this->optionMapper->insert($newOption);
		} catch (Exception $e) {
			$this->logger->error('Error while adding option', [
				'optionText' => json_encode($newOption),
				'pollId' => $pollId,
				'exceptionMessage' => $e->getMessage(),
			]);
			// TODO: Change exception catch to actual exception
			// Currently OC\DB\Exceptions\DbalException is thrown instead of
			// UniqueConstraintViolationException
			// since the exception is from private namespace, we check the type string
			if (get_class($e) === 'OC\DB\Exceptions\DbalException' && $e->getReason() === Exception::REASON_UNIQUE_CONSTRAINT_VIOLATION) {

				// Option already exists, so we need to update the existing one
				// and remove deleted setting
				$option = $this->optionMapper->findByPollAndText($pollId, $newOption->getPollOptionHash(), true);
				$option->setDeleted(0);

				$newOption = $this->optionMapper->update($option);

			} else {
				throw $e;
			}
		}

		if ($voteYes) {
			// Set the vote for the new option on request
			$this->voteService->set($newOption, Vote::VOTE_YES);
		}

		$this->eventDispatcher->dispatchTyped(new OptionCreatedEvent($newOption));

		return $newOption;
	}

methods.Service/OptionService.php::update:
function update(
		int $optionId,
		string $pollOptionText = '',
		?DateTimeImmutable $dateTime = null,
		DateInterval $interval = new DateInterval('PT0S'),
	): Option {
		$option = $this->optionMapper->find($optionId);
		$this->getPoll($option->getPollId())->request(Poll::PERMISSION_POLL_EDIT);

		if ($this->poll->getType() === Poll::TYPE_TEXT) {
			if (!$pollOptionText) {
				throw new InsufficientAttributesException('Text is required for text polls');
			}
			$option->setText($pollOptionText);
		}

		if ($this->poll->getType() === Poll::TYPE_DATE) {
			if ($dateTime === null) {
				throw new InsufficientAttributesException('Date time is required for date polls');
			}
			$option->setDateTime($dateTime);
			$option->setInterval($interval);
		}

		$option = $this->optionMapper->update($option);
		$this->eventDispatcher->dispatchTyped(new OptionUpdatedEvent($option));

		return $option;
	}

