methods.Service/ShareService.php::delete:
function delete(Share $share, bool $restore = false): Share {
		$pollId = $share->getPollId();
		$groupId = $share->getGroupId();
		if ($pollId === null && $groupId !== null) {
			$this->pollGroupMapper->find($groupId)
				->request(PollGroup::PERMISSION_POLL_GROUP_EDIT);
		} elseif ($pollId !== null && $groupId === null) {
			$this->pollMapper->get($pollId)
				->request(Poll::PERMISSION_POLL_EDIT);
		}

		$share->setDeleted($restore ? 0 : time());
		$this->shareMapper->update($share);

		// skip event when deleting a poll group share
		if ($pollId !== null) {
			$this->eventDispatcher->dispatchTyped(new ShareDeletedEvent($share));
		}
		return $share;
	}

methods.Service/ShareService.php::createPublicSh:
function createPublicShare(int $pollId): Share {
		$this->pollMapper->get($pollId)
			->request(Poll::PERMISSION_POLL_EDIT)
			->request(Poll::PERMISSION_SHARE_ADD)
			->request(Poll::PERMISSION_SHARE_ADD_EXTERNAL);
		$this->appSettings->getPublicSharesAllowed();

		$shareUser = UserMapper::createUserObject(UserBase::TYPE_PUBLIC, '');

		try {
			$share = $this->createNewShare($pollId, $shareUser);
		} catch (ShareAlreadyExistsException $e) {
			$share = $e->getShare();
		}

		$this->eventDispatcher->dispatchTyped(new ShareCreateEvent($share));
		return $share;
	}

methods.Service/ShareService.php::createShare:
function createShare(int $pollOrPollGroupId, UserBase $userGroup, string $purpose = 'poll'): Share {
		if ($purpose === 'poll') {
			$poll = $this->pollMapper->get($pollOrPollGroupId)
				->request(Poll::PERMISSION_POLL_EDIT)
				->request(Poll::PERMISSION_SHARE_ADD);

			if (in_array($userGroup->getType(), [
				UserBase::TYPE_GHOST,
				UserBase::TYPE_CONTACT,
				UserBase::TYPE_CONTACTGROUP,
				UserBase::TYPE_EMAIL,
				UserBase::TYPE_EXTERNAL,
			], true)) {
				$poll->request(Poll::PERMISSION_SHARE_ADD_EXTERNAL);
			}
			$preventInvitation = false;
		} else {
			$preventInvitation = true;
		}

		try {
			$share = $this->createNewShare($pollOrPollGroupId, $userGroup, $preventInvitation, $purpose);
		} catch (ShareAlreadyExistsException $e) {
			$share = $e->getShare();
		}

		if ($share->getPollId() !== null) {
			$this->eventDispatcher->dispatchTyped(new ShareCreateEvent($share));
		}
		return $share;
	}

methods.Service/ShareService.php::sendInvitation:
function sendInvitation(Share $share, SentResult &$sentResult = new SentResult()): SentResult {
		if (in_array($share->getType(), [Share::TYPE_USER, Share::TYPE_ADMIN], true)) {
			$this->notificationService->sendInvitation($share->getPollIdOrFail(), $share->getUserId());
		} elseif ($share->getType() === Share::TYPE_GROUP) {
			foreach ($share->resolveUser()->getMembers() as $member) {
				$this->notificationService->sendInvitation($share->getPollIdOrFail(), $member->getId());
			}
		}

		return $this->mailService->sendInvitation($share, $sentResult);
	}

methods.Service/ShareService.php::createNewShare:
function createNewShare(
		int $pollOrPollGroupId,
		UserBase $userGroup,
		bool $preventInvitation = false,
		string $purpose = 'poll',
	): Share {
		$preventInvitation = $userGroup->getType() === UserBase::TYPE_PUBLIC ?: $preventInvitation;

		// Generate a unique id
		$token = $this->generateToken();

		$this->share = new Share();

		if ($purpose === 'poll') {
			$this->share->setPollId($pollOrPollGroupId);
			$this->share->setGroupId(null);
		} else {
			$this->share->setPollId(null);
			$this->share->setGroupId($pollOrPollGroupId);
		}

		$this->share->setToken($token);
		$this->share->setFromUserObject($userGroup, $token, $purpose);
		$this->share->setInvitationSent($preventInvitation ? time() : 0);

		try {
			$this->share = $this->shareMapper->insert($this->share);
			// return new created share
			return $this->share;
		} catch (Exception $e) {
			// TODO: Change exception catch to actual exception
			// Currently OC\DB\Exceptions\DbalException is thrown instead of
			// UniqueConstraintViolationException
			// since the exception is from private namespace, we check the type string
			if (get_class($e) === 'OC\DB\Exceptions\DbalException' && $e->getReason() === Exception::REASON_UNIQUE_CONSTRAINT_VIOLATION) {

				$share = $this->shareMapper->findByPollAndUser($pollOrPollGroupId, $this->share->getUserId(), true);
				if ($share->getDeleted()) {
					// Deleted share exist, restore deleted share and generate new token
					$share->setDeleted(0);
					$share->setLocked(0);
					$share->setInvitationSent(0);
					$share->setToken($this->generateToken());
					if ($share->getType() === UserBase::TYPE_ADMIN) {
						$share->setType(UserBase::TYPE_USER);
					}
					$share = $this->shareMapper->update($share);
				}
				// return existing undeleted share
				throw new ShareAlreadyExistsException('Share already exists', $share);
			}
			// other error
			throw $e;
		}
	}

