methods.Db/OptionMapper.php::findByPoll:
function findByPoll(int $pollId, bool $hideResults = false, bool $getDeleted = false): array {
		$qb = $this->buildQuery($hideResults);
		$qb->where($qb->expr()->eq(self::TABLE . '.poll_id', $qb->createNamedParameter($pollId, IQueryBuilder::PARAM_INT)));
		if (!$getDeleted) {
			$qb->andWhere($qb->expr()->eq(self::TABLE . '.deleted', $qb->expr()->literal(0, IQueryBuilder::PARAM_INT)));
		}

		return $this->findEntities($qb);
	}

methods.Db/ShareMapper.php::findByPoll:
function findByPoll(int $pollId, array $groupIds = [], bool $getDeleted = false): array {
		$qb = $this->db->getQueryBuilder();

		$qb->select(self::TABLE . '.*')
			->from($this->getTableName(), self::TABLE)
			->groupBy(self::TABLE . '.id')
			->where($qb->expr()->eq(self::TABLE . '.poll_id', $qb->createNamedParameter($pollId, IQueryBuilder::PARAM_INT)));

		if (!empty($groupIds)) {
			$qb->orWhere(
				$qb->expr()->in(self::TABLE . '.group_id', $qb->createNamedParameter($groupIds, IQueryBuilder::PARAM_INT_ARRAY))
			);
		}
		if (!$getDeleted) {
			$qb->andWhere($qb->expr()->eq(self::TABLE . '.deleted', $qb->expr()->literal(0, IQueryBuilder::PARAM_INT)));
		}

		$this->joinUserVoteCount($qb, self::TABLE);
		$this->joinAnon($qb, self::TABLE);

		return $this->findEntities($qb);
	}

