methods.Model/Settings/AppSettings.php::getBoole:
function getBooleanSetting(string $key, string $groupKey = self::NO_GROUPCHECK, bool $default = true, string $app = Application::APP_ID): bool {
		// key missing or invalid, return default
		if (!$this->checkSettingType($key, IAppConfig::VALUE_BOOL, $app)) {
			return $default;
		}

		// no group check or user is not logged in, just return the boolean setting value
		if ($groupKey === self::NO_GROUPCHECK || !$this->userSession->getIsLoggedIn()) {
			return $this->appConfig->getValueBool($app, $key, $default);
		}

		// user is logged in and group check is required
		return $this->appConfig->getValueBool($app, $key, $default) || $this->isMember($this->getGroupSetting($groupKey));
	}

methods.Db/Poll.php::setAnonymousSafe:
function setAnonymousSafe(bool|int $value): void {
		// if anonymous is locked, do not allow changes
		if ($this->getAnonymous() < 0) {
			return;
		}

		if (!$this->getAllowDeanonymize() && $value > 0) {
			// if the owner of the poll is restricted, lock the anonymous
			// setting once it is set
			// lock anonymous setting by setting it to negative value
			$value = -1;
		}
		$this->setAnonymous((int)$value);
	}

